/* The Vault – Bower Street (Buch S. 76–93). Übersetzung aus dem Englischen. */
window.TA_VAULT = window.TA_VAULT || {};
TA_VAULT["bower-street"] = {
 cw: "Gedächtnisverlust, Tierleid, Ertrinken, Tod eines Elternteils, Scheidung",
 chaosP: 80,
 chaos: [
  {k:2, n:"Verderben", en:"Corrupt", x:"Gealterte Gegenstände werden zu makelloser Neuheit wiederhergestellt. Bei Berührung oder anderer körperlicher Einwirkung zerbröckeln sie und verblassen."},
  {k:4, n:"Manifestieren", en:"Manifest", x:"Die Anomalie formt eine verzerrte, flackernde Wiedergabe einer Person, eines Ortes oder eines Dinges, das sie gestohlen hat. Diese Anomalie will nicht im herkömmlichen Sinne schaden: Sie will Menschen und Dinge hineinziehen und festhalten und nutzt dafür Vertrautheit als Köder.\n\n**Gestalt (täuschend):** Die Anomalie verwendet das Abbild einer Person, die sie zuvor gefangen hat. Oft wird sie als die hilfloseste Version ihrer selbst dargestellt oder als eine Person aus der Vergangenheit eines Gefangenen. Zur Auswahl stehen derzeit diejenigen, die aus Sycamore Heights verschwunden sind – anfangs Fumiko Hashimoto, ein Elektriker namens Jacob Mills, der in der Gegend beauftragt war, und ein Student namens Caleb Coleman, der seinen verlorenen Hund suchte. Das kann sich erweitern, wenn die Anomalie mehr Menschen gefangen nimmt. Sie rufen um Hilfe und versuchen, einen Agenten oder anderen Zivilisten in den Keller zu locken.\n\n**Vision (einsperrend):** Die Anomalie will, dass ihre Ziele in ihrer Reichweite bleiben. Dafür versieht sie oft Gegenstände oder weniger intelligente Wesen, etwa gefangene Tiere, mit einer Art Falle. Sie versucht, jeden, der einen dieser Gegenstände berührt, in einer tröstlichen Erinnerung festzusetzen. So macht sie ihn bequem genug, um in den Keller zu ziehen und als Brennstoff für die Anomalie benutzt zu werden."},
  {k:5, n:"Anziehen", en:"Attract", x:"Einer der Anwohner ruft hinter einer jetzt verschlossenen Tür hervor, rüttelt am Türknauf und bittet um Hilfe."},
  {k:6, n:"Ausdehnen", en:"Expand", x:"Ein weiterer Raum des Hauses wird von einer Masse aus verhedderten alten VHS-Bändern umschlossen, zähflüssig und weit schwerer, als sie sein dürfte, als wäre sie von Flüssigkeit durchtränkt, obwohl nichts davon tropft."},
  {k:8, n:"Versetzen", en:"Displace", x:"Die Anomalie zieht die Agenten in eine unerreichbare Vergangenheit zurück. Der Raum, in dem sie sich befinden, formt sich zu einem aus den Erinnerungen der Zwillinge um, in dem eine der Zwillinge oder beide in ihrer jüngeren Gestalt anwesend sind. Ist es Caitlin, ist die Nachbildung fest und fühlt sich fast echt an. Ist es Evie, flackert das Bild; es ist mehr eine Manifestation der Anomalie, gefiltert durch Caitlins Erinnerungen."}
 ],
 ziele: [
  {art:"bel", n:3, x:"für den Agenten, der die meisten freundlichen Winke erhält"},
  {art:"bel", n:1, x:"für jedes befreundete Tier"},
  {art:"ver", n:1, x:"für jeden Fall von Sachbeschädigung"}
 ],
 reiter: {
  profil: [
   {t:"Fundstück", p:77, b:[
    {t:"handout", art:"abschrift", h:"Abschrift eines 911-Anrufs", x:[
     "Der folgende Auszug wurde von einem 911-Anruf einer Person aus Sycamore Heights vor einer Woche abgeschrieben.",
     "LEITSTELLE: Hier ist 9-1-1, Allison am Apparat. Was ist Ihr Notfall?",
     "J.H.: Hi, okay. Vielleicht ist das dumm, aber – ich möchte melden, dass meine Frau verschwunden ist.",
     "LEITSTELLE: Ihre Frau ist verschwunden, Sir?",
     "J.H.: Sie – Sie ist heute Nachmittag rausgegangen und nicht nach Hause gekommen. Sie hat das Haus verlassen und ist nicht zurückgekommen. Ich bin herumgelaufen und habe nach ihr gesucht, und niemand hat sie gesehen. Ich meine, es wird langsam spät, also … ich mache mir Sorgen. Ich weiß nicht, ob etwas passiert ist, aber es sieht ihr nicht ähnlich.",
     "LEITSTELLE: Okay. Ich brauche ein paar Angaben von Ihnen, dann kann ich jemanden losschicken, der sich umsieht. Fangen wir mit Ihrer Telefonnummer an.",
     "J.H.: [geschwärzt]",
     "LEITSTELLE: Danke. Ihre Adresse?",
     "J.H.: 1059 Bower Street.",
     "LEITSTELLE: Und Ihr Name?",
     "J.H.: Justin. Justin Hamamoto.",
     "LEITSTELLE: Hamamoto. Okay. Perfekt. Wie heißt Ihre Frau?",
     "J.H.: Fumiko.",
     "LEITSTELLE: Fumiko Hamamoto?",
     "J.H.: Ja. Ja, genau. (schnieft) Entschuldigung.",
     "LEITSTELLE: Schon gut. Wann hat Ihre Frau heute Nachmittag das Haus verlassen, Justin?",
     "J.H.: 13:20 Uhr, vielleicht? Ein bisschen vor 13:30 Uhr.",
     "LEITSTELLE: Okay. Wohin wollte sie? War sie zu Fuß, mit dem Auto?",
     "J.H.: Sie ist joggen gegangen. Also zu Fuß. Sie läuft jeden Tag eine Runde durch die Nachbarschaft. Sie hatte ihre Sportsachen an und hat ihre Schlüssel und ihre Wasserflasche mitgenommen. Es war wie immer. Ich war bei der Arbeit, ich arbeite von zu Hause. Es ist nach dem Abendessen und sie ist nicht zurück. Ich –",
     "LEITSTELLE: Okay. Langsam. Sagen Sie mir, was sie anhatte.",
     "J.H.: Sie trug ein hellblaues Tanktop. Weiße Turnschuhe. Die sind schon ziemlich alt, deshalb sehen sie ein bisschen grau aus. Sie waren weiß mit pinken Akzenten. Oder – das ist ihr altes Paar. Das war letzte Woche. Tut mir leid, ich bin ein bisschen …",
     "LEITSTELLE: … Justin?",
     "(Etwa zwanzig Sekunden Stille.)",
     "J.H.: Entschuldigung, ich …",
     "LEITSTELLE: Hallo?",
     "J.H.: Wer ist da noch mal? Worum ging es gerade …? Tut mir leid.",
     "LEITSTELLE: Ich bin –",
     "(Ein scharfer Stoß Rauschen.)",
     "LEITSTELLE: … nicht sicher. Wurde dieser Anruf irrtümlich getätigt?",
     "J.H.: Ich glaube schon. Ja. Ja. Tut mir leid.",
     "LEITSTELLE: Schon gut, Sir. Das passiert öfter, als Sie denken.",
     "(Anruf endet.)"
    ]}
   ]},
   {t:"Überblick", p:78, b:[
    {t:"profil",
     lead:"Unter dem bilderbuchhaften Anstrich von Sycamore Heights gärt etwas. Im Labyrinth aus sonnengebleichten Gehwegen, gepflegten Rasenflächen und identischen Häusern hat sich ein Loch in der Welt aufgetan, etwa neunzehn Zentimeter lang und zehn Zentimeter breit. Alles rollt bergab, und alles rutscht in die Erinnerung – du musst nur loslassen.\n\nDie Anomalie, die sich unter 1063 Bower Street versteckt, nährt sich von einem falschen Glück, das aus wahnhafter Nostalgie entsteht. In dieser harmlosen Vorortsiedlung hat sie das perfekte Ziel gefunden: Caitlin Rowe, eine Künstlerin, die das Haus ihrer Eltern nach deren Tod geerbt hat. Caitlin hat ihr ganzes Leben lang gewünscht, in ihre Vergangenheit zurückzukönnen, und nun ist sie umgeben von Erinnerungen an das, was sie vermisst: die Freiheit der Kindheit, die Fürsorge ihrer Eltern und die Gesellschaft ihrer Zwillingsschwester Evie. Die Anomalie hat ihr all das zurückgegeben, indem sie sie im Keller gefangen und an ein endloses VHS-Band voller Erinnerungen gekettet hat.\n\nNun hungrig nach mehr, greift die Anomalie auch nach dem Rest der Nachbarschaft und zerrt auch ihn zurück in seine Vergangenheit.",
     fokus:"Der Trost, in der Vergangenheit zu leben. Die Anomalie wird von Gedanken an eine Zeit genährt, die durch die verschwommene Distanz der Erinnerung unkompliziert und angenehm geworden ist.",
     domaene:"Der Keller von 1063 Bower Street.",
     impuls:"Menschen in ihren Erinnerungen an eine wärmere und behaglichere Vergangenheit festzusetzen. Die Anomalie entfernt jüngere Erinnerungen und Konfliktquellen aus dem Leben der Menschen, sodass diese überzeugt sind, in einer früheren Epoche zu leben, nach der sie sich sehnen. Teile der Nachbarschaft, die Reibung verursachen (*Tiere, die zu jung sind, um in der richtigen Zeit existiert zu haben, Menschen, die sich anders entwickelt haben, als du sie in Erinnerung hast, usw.*), werden verwandelt oder entfernt, um den traumgleichen Komfort der Bewohner der Bower Street zu erhalten."},
    {t:"h", x:"Geschichte"},
    "1063 Bower Street glich jedem anderen Haus in der Bower Street, auch wenn jetzt die Farbe abblättert und das Fundament fault. Das Bemerkenswerteste, was unter diesem Dach je geschah, war die Kindheit der Rowe-Zwillinge Caitlin und Evie. Zwillinge, die miteinander wuchsen und sich veränderten, wie Zwillinge es oft tun.",
    "Im Lauf der Jahre wurden die Rowe-Zwillinge erwachsen, zogen aus und gingen ihren eigenen Karrieren und Leben nach. Caitlin Rowe zog als Malerin über Jahre von Wohnung zu Wohnung. Ihre Schwester Evie – inzwischen durch Heirat Evie Wright – hatte einen gut bezahlten Konzernjob. Als ihre Eltern starben, war das Schicksal von 1063 Bower Street klar. Caitlin zog wieder ein und machte dieses Stück der gemeinsamen Vergangenheit der Zwillinge zu ihrer Gegenwart.",
    "Zum letzten Weihnachtsfest feierte die ganze Familie zusammen. Die Zwillinge gingen einen Teil des alten Krempels im Keller durch. Mit einem kaum funktionierenden VHS-Player verbrachten sie lange Nächte damit, alte Heimvideos anzusehen. Wenige Monate später starben ihre Eltern, und beim Aufräumen des Hauses spielte Caitlin eines der Bänder noch einmal ab. Seitdem hat es nicht mehr aufgehört zu laufen.",
    {t:"h", x:"Erscheinung"},
    "Eine Videokassette, die in einem abgewetzten, klickenden Videorekorder steckt. Das Etikett, mit Permanentmarker überkritzelt, ist bis zur Unleserlichkeit verblasst. Freiliegendes, beschädigtes Band sammelt sich darum zu einer glatten schwarzen Pfütze und quillt wie glänzende schwarze Eingeweide aus dem Schlitz. Der Fernseher flackert durch eine Reihe verschwommener Bilder von vor ewigen Zeiten, obwohl er nicht eingesteckt ist.",
    {t:"h", x:"Aktuelle Lage"},
    "Die Anomalie frisst sich in die umliegende Bebauung. Die Landschaft selbst verzieht sich, mit einer kaum wahrnehmbaren Neigung im Boden, die zum Keller führt, der sie beherbergt. In den letzten Monaten sind mit rasch zunehmender Häufigkeit mehrere Nachbarn und Haustiere verschwunden. Seit einiger Zeit hat niemand mehr Caitlin Rowe gesehen, auch wenn sich gelegentlich etwas hinter den Jalousien und Vorhängen von 1063 regt. Was sich in diesen Fluren bewegt, zumindest über der Erde, ist nicht mehr Caitlin, sondern der Einfluss der Anomalie, der versucht, die Welt umzuformen und dabei Energie aus ihr und anderen in Sycamore Heights zu ziehen. Caitlin selbst ist im Keller ihres eigenen Elternhauses gefangen, in schwarzes Band gebunden, und sieht zu, wie ihre und die Vergangenheits-Ichs ihrer Schwester Spiele spielen, am Rand des Pools entlangrennen und abwechselnd auf der Treppe Verstecken spielen. Die Anomalie spielt alte Erinnerungen ab und löscht, was neu ist."
   ]}
  ],
  vor: [
   {t:"Morgenbesprechung", p:79, b:[
    {t:"morgen", x:[
     "Eine Beziehung, die vor Kurzem nach Sycamore Heights gezogen ist, wurde unerwartet mit einer Katze vereint, die vor zwanzig Jahren aus ihrem Haus verschwunden war. Sie ist so alt wie bei ihrem Verschwinden, und es gibt Fotobeweise dafür.",
     "Ein Agent findet seine Badewanne überlaufend vor. Solange er nicht damit interagiert, ist das Wasser leuchtend blau – so, wie es in einem Schwimmbad aussieht.",
     "Ein Verwandter oder Freund aus der Vergangenheit eines Agenten ruft ihn aus heiterem Himmel an und bittet darum, dass man ihm eine Geschichte aus ihrer gemeinsamen Zeit vor Jahren erzählt.",
     "CTO Evie Wright, lächelnd, braunes Haar zu einem ordentlichen Bob geschnitten und in einem maßgeschneiderten Anzug, ist in einem Videointerview zur Veröffentlichung eines neuen Elektrofahrzeugs zu sehen. Einige Augenblicke nach Beginn scheint ihr Blick am Interviewer vorbei zur Kamera zu wandern, als sähe sie etwas in der Linse. Ihr kommen die Tränen, dann wischt sie sie weg, lacht und entschuldigt sich für die Unterbrechung. Sie hat sich nur an etwas von vor langer Zeit erinnert.",
     "Auf dem Weg zur Arbeit sieht ein Agent ein neues, halbfertiges Wandbild an einer Hauswand. Es ist hell und comichaft, fast kindlich in seiner greifbaren Freude. Es zeigt eine Frau in vielen Farben, die nach der linken Seite des Werks greift, nach etwas, das der Form nach eine identische Version ihrer selbst ist. Die Version links hat ein verschwommenes, in einer Farbmasse verlorenes Gesicht, als bestünde sie aus Flüssigkeit, die zur linken Außenseite der Wand zurückgezogen wird. Die Initialen unten rechts lauten CR."
    ]}
   ]},
   {t:"Einsatzbesprechung", p:79, b:[
    {t:"vorlesen", b:[
     "Die Agency hat letzte Nacht einen 911-Anruf von Justin Hamamoto abgefangen, der mitten im Gespräch, in dem er seine vermisste Frau meldete, orientierungslos wurde und den Anruf vorzeitig beendete. Eine Abschrift des Anrufs steht den Agenten auf der ersten Seite dieses Einsatzes zur Verfügung. In der Nachricht gibt er an, in 1059 Bower St. zu wohnen.",
     "Daten zeigen einen bemerkenswerten Anstieg von Vermisstenmeldungen für Haustiere in Sycamore Heights, rund um die Bower Street. Bei näherer Nachfrage erinnern sich die meisten Leute, die diese Plakate aufgehängt haben, nicht daran, es getan zu haben. Die Agency hat ein Bild eines dieser Vermisstenplakate erhalten.",
     "Das Plakat ist vergilbt und abgenutzt und zeigt ein Bild einer schwarzen Katze mit einem weißen Fleck über dem linken Auge. Oben auf dem Blatt steht: **„KATZE VERMISST. Falls gefunden, bitte zu 1058 Bower St. bringen.“**",
     {t:"handout", art:"schild", h:"Vermisstenplakat", x:["KATZE VERMISST. Falls gefunden, bitte zu 1058 Bower St. bringen."]}
    ]}
   ]}
  ],
  erm: [
   {t:"Sycamore Heights", p:81, b:[
    "Sycamore Heights ist eine durchschnittliche Vorortsiedlung, im Guten wie im Schlechten. Die Leute führen ihre Hunde aus, beschweren sich bei der Eigentümergemeinschaft und führen ansonsten unauffällige Leben zwischen Reihen identischer Häuser. Die Rasenflächen sind sorgfältig gepflegt. Die Nachbarn sind distanziert und misstrauisch, kennen aber gegenseitig ihre Namen. Ein Mann wässert den Rasen, allein auf einer ruhigen Straße.",
    {t:"hinweis", art:"gew", h:"Das sehen Agenten, sobald sie ankommen:", x:[
     "Ein Mann, der auf die Beschreibung von Justin Hamamoto passt, wässert den Rasen vor seinem Haus.",
     "Ein weiteres Vermisstenplakat für diese schwarze Katze, mit Kontaktangaben für Rebecca Hawcett in 1058 Bower Street."
    ]},
    {t:"hinweis", art:"anom", h:"Das erfahren Agenten, wenn sie viel Zeit draußen verbringen oder anomale Methoden einsetzen:", x:[
     "Der Boden in der Nachbarschaft hat eine merkwürdige, ganz leichte Wölbung. Wenn sie sich die Zeit nehmen, sie zu messen, stellen sie fest, dass es nicht nur eine Richtung ist. Es ist eine Art Kegel, der unten zu 1063 Bower Street führt.",
     "Es gibt in dieser Nachbarschaft eine viel höhere Zahl an Tieren als normal: streunende Katzen, Hunde, sogar einige Ratten und Mäuse. Sobald man diesen Trend erkennt, ist offensichtlich, dass sie sich um 1063 Bower St. konzentrieren."
    ]},
    {t:"h", x:"1059 Bower St."},
    "Vor 1059 Bower Street steht ein Mann, der benommen neben einem Beet mit lila Pfingstrosen verweilt. Der Gartenschlauch in seiner Hand tropft auf den Boden, und das Blumenbeet ist offensichtlich überwässert. Justin Hamamoto (er/ihm) ist ein schlanker Japaner mit einer kleinen Brille auf der Nase und schwarzem, ziemlich kurz geschnittenem, aber ungekämmtem Haar. Der dunkelblaue Pullover, den er trägt, wurde von Hand gestrickt.",
    "Der Blick durch die Fenster ins Haus zeigt zunächst ein ordentlich gepflegtes Heim. Die Einrichtung ist warm, aber schlicht. Im Wohnzimmer liegt deutlich sichtbar ein dunkelvioletter Futon, aufgerollt und zur Seite gestellt, ein wenig schlampig und halb ausgeklappt. Obenauf liegt eine Haarspange.",
    "Bilderrahmen im Haus sind mit der Vorderseite nach unten aufgestellt, bis auf einen. Es ist ein Foto eines Paares in den Zwanzigern: eine jüngere Version von Justin und eine Frau mit windzerzaustem Bob – Fumiko.",
    "**Wenn die Agenten nach Fumiko fragen,** ist er unbesorgt. Er ist sicher, dass sie im Laden ist, oder vielleicht auf einer Reise, oder vielleicht ist sie beim Arzt?",
    "**Wenn Agenten ihm die Aufnahme seines Anrufs vorspielen,** gerät er in Not. Er weiß, wer Fumiko ist, aber nichts von dem, was gerade mit ihr los ist, ergibt Sinn. Sie ist nicht gestern verschwunden. Daran würde er sich erinnern.",
    "**Wenn er nach dem Wohnzimmer gefragt oder mit Jodies Klatsch konfrontiert wird,** wird er unbehaglich, bestreitet alles und ist deutlich orientierungslos. Sie haben nie gestritten. Alles ist in Ordnung. Sie ist nur auf einer Reise.",
    {t:"hinweis", art:"gew", h:"Das erfahren Agenten leicht, wenn sie kurz mit Justin sprechen:", x:[
     "Er ist mit Fumiko Hamamoto verheiratet. **Er erinnert sich nicht, 911 angerufen zu haben.**",
     "Er ist ein 38-jähriger Marketingmanager.",
     "Er trägt einen handgestrickten Pullover. Darauf angesprochen, lächelt er und sagt, dass **Fumiko ihn für ihn gestrickt hat** als verspätetes Hochzeitsgeschenk. Agenten, die etwas vom Stricken verstehen, erkennen vielleicht ein paar kleine Fehler in der Arbeit, aber es ist deutlich etwas, das er schätzt."
    ]},
    "**Wenn die Agenten so wirken, als streiften sie durch die Nachbarschaft,** bittet Justin sie, für ihn einen Rasentrimmer zu dem alten Ehepaar in 1063 Bower St. zurückzubringen. Es sind nur ein paar Türen weiter, aber die beiden verwickeln ihn immer in ein langes Gespräch.",
    {t:"h", x:"1058 Bower St."},
    "**Rebecca Hawcett (sie/ihr)** ist eine 32-jährige Buchkritikerin, die mit ihrer Frau **Jodie (sie/ihr)** in 1058 Bower Street lebt. Als die Agenten ankommen, erkennt sie das Plakat nicht. Jodie unterbricht aus dem anderen Zimmer und besteht darauf, dass sie es sehr wohl erkennt. Ihre schwarze Katze von dem Plakat, Cooper, haben sie seit über zwei Wochen nicht gesehen.",
    "Während des Besuchs der Agenten kommt ein verspielter orangefarbener Tigerkater mit leuchtend bernsteinfarbenen Augen ins Zimmer spaziert. Rebecca girrt der Katze zu, nennt ihn „mein kleiner Felix“ und nimmt ihn wie ein Baby auf den Arm. Jodie bleibt stoisch und bittet Rebecca schließlich, Felix in ein anderes Zimmer zu bringen.",
    "**Wenn Jodie nach der Begegnung mit Felix mit den Agenten allein ist,** sagt sie, dass sie weiß, dass Felix, eine Katze, die genau so aussah, Rebeccas erste Katze in der Kindheit war. Er starb, als sie siebzehn war. Sie besteht darauf, dass diese Katze nicht Felix ist und erst gestern aufgetaucht ist, aber er verhält sich genau wie der Felix, der ihr beschrieben wurde. Rebecca besteht darauf, dass das Felix ist, und die beiden streiten sich darüber, ob die Katze überhaupt gestorben ist.",
    "Jodie findet die ganze Sache sehr beunruhigend. Erst verschwindet Cooper, dann kehrt Felix zurück? Aber Rebecca scheint Cooper völlig zu vergessen.",
    {t:"hinweis", art:"gew", h:"Das erfahren Agenten von dem Paar, wenn Jodie sie unterhaltsam findet:", x:[
     "Auf die Hamamotos angesprochen, gibt Jodie zu, eine neugierige Nachbarin zu sein. Sie verrät, dass sie bei späten Spaziergängen sehr laute Streitereien zwischen Justin und Fumiko gehört hat. Es kam ihr so vor, als stünde die Ehe auf der Kippe.",
     "Zum Thema Klatsch erzählt sie auch, dass sie schon länger niemanden mehr aus 1063 Bower St. hat herauskommen sehen, was seltsam ist, weil gerade erst eine Frau namens Evie eingezogen ist, nachdem sie das Haus von ihren Eltern geerbt hat, die vor ein paar Monaten gestorben sind.",
     "Rebecca beschwert sich bei ihrer Rückkehr, dass Jodie sich jetzt so für das Leben aller anderen interessiere, aber nie über sich selbst oder ihre Vergangenheit reden wolle. Jodie verzieht sichtbar das Gesicht bei dem Vorwurf und beteuert, sie wisse eben, dass es nicht viel aus ihrem Leben vor Rebecca gibt, woran sie sich erinnern möchte. Es ist klar, dass dies ein oft geführtes Gespräch ist."
    ]}
   ]},
   {t:"1063 Bower St.", p:83, b:[
    "Das Haus ist still, die Fenster dunkel. Drinnen ist keine Bewegung zu sehen, auch wenn gelegentlich ein Vorhang merkwürdig flattern mag. Ein alter Baum reckt sich zum Himmel. Das Gras im Garten ist uneben, aber es gab zumindest einen kürzlichen Versuch, es zu mähen. An der Seite des Hauses führt ein Tor in den Hinterhof. Die Angeln sind verrostet. Es wurde mit einem neueren Vorhängeschloss verschlossen. Die Fußmatte ist schlicht und würdevoll, mit „Welcome“ in der Mitte.",
    "**Wenn sich die Agenten nähern,** bricht aus dem Inneren ein Schwall statisches Rauschen los. Durch eines der Vorderfenster ist ein Fernseher zu sehen, der sich an- und ausschaltet oder vielleicht durch Bilder flackert, die hell und dann sehr dunkel sind. Rufen oder Klopfen bleibt ohne Antwort.",
    {t:"hinweis", art:"gew", h:"Das erfahren Agenten, während sie irgendwo Blicke auf sich spüren:", x:[
     "Ein Werbeflyer einer Fensteraustauschfirma wurde in die Haustür geklemmt. Er zeigt einige Abnutzungsspuren durch Wind und Wetter – er ist schon eine Weile hier.",
     "Ein Ersatzschlüssel für die Haustür ist in einem Blumenkübel neben der Tür versteckt."
    ]}
   ]},
   {t:"Hinterhof", p:83, b:[
    "Eine leicht gebogene Palme mit ungesund grauer Rinde steht in der hinteren rechten Ecke und lehnt sich über die Hofmauer. Ein baufälliger Schuppen kauert in der Ecke daneben. Das Hauptmerkmal des Hinterhofs ist der große leere Swimmingpool, dessen Inneres knochenweiß gebleicht ist.",
    {t:"hinweis", art:"gew", h:"Das erfahren Agenten leicht, wenn sie den Hinterhof untersuchen:", x:[
     "Der Baum hat gesunde Wurzeln, aber eine Art schwarze Fäulnis kriecht den Stamm hinauf.",
     "Ein Rasenmäher steht trostlos in der Ecke, zur Seite geschoben, als müsste er aus den Augen und aus dem Sinn sein.",
     "Der Schuppen ist verschlossen.",
     "Aus bestimmten Winkeln betrachtet, scheint der Pool mit vollkommen blauem Wasser gefüllt zu sein.",
     "Auf dem Boden des leeren Pools liegt ein kleiner glitzernder Gegenstand."
    ]},
    {t:"h", x:"In den Pool steigen"},
    "Auf dem Boden des leeren Pools liegt ein kupferner Schlüssel. Sobald jemand in den Pool klettert und den Schlüssel aufhebt, füllt sich der Pool schlagartig mit einer zähflüssigen, krankhaft algenverseuchten grünen Flüssigkeit, schwer und klebrig. Wer hineingestiegen ist, sitzt schnell fest und ertrinkt ohne übernatürliche Hilfe bald.",
    {t:"h", x:"Im Schuppen"},
    "**Wenn Agenten den Schuppen öffnen,** finden sie eine Vielzahl rostiger Gartengeräte, alte Düngersäcke und ein blaues Haustierhalsband mit einer Marke, auf der der Name von der Zeit abgetragen ist. Nur die ersten beiden Buchstaben sind lesbar: ***OL.***"
   ]},
   {t:"Garage", p:84, b:[
    "In der Garage steht eine abgewetzte weiße Limousine. Die Fahrertür ist verbeult. Eine Lampe hängt tief, die Glühbirne ist tot. Sonnenlicht fällt durch einen Spalt unter der Tür zum Hinterhof herein, das Holz verbogen und verzogen durch Wasserschäden. An den Wänden stehen Regale voller Elektrowerkzeuge, alter Pappkartons und anderem Krempel.",
    "Die Limousine ist verschlossen. Im Wagen liegt eine halb ausgetrunkene Wasserflasche. Zulassung und Versicherung lauten auf Caitlin Rowe. Kofferraum und Rücksitz enthalten mehrere offene Umzugskartons.",
    {t:"h", x:"Kartons in der Limousine"},
    "Die meisten Kartons sind leer. Einer im Kofferraum ist bei näherer Untersuchung voll mit brackigem Wasser. Die Außenseite des Kartons ist vollkommen trocken. Er ist außergewöhnlich schwer. Wird versucht, den Karton zu bewegen, durchweicht das Wasser schnell den Pappkarton und läuft hindurch – Wasser strömt ununterbrochen aus dem Karton, bis die Anomalie erledigt ist.",
    {t:"hinweis", art:"gew", h:"Das erfahren Agenten leicht, wenn sie die Garage erkunden:", x:[
     "Die neuesten Kartons in der Garage wurden hastig mit Permanentmarker mit JUNK beschriftet. Es sind drei, alle halb gefüllt. Allerlei Gegenstände liegen darin – altes Spielzeug, Sets von klapprig aussehenden Stiften, altmodisches Porzellan.",
     "Auf einem der Kartons liegt ein altes Skizzenbuch, aufgeschlagen auf einer Seite mit einer groben Strichmännchenfamilie vor einem Haus, das, zumindest der Form nach, jedem der Vorstadthäuser um sie herum gleicht. Die zwei größeren Figuren sind in kindlicher Schmiererei mit Mom und Dad beschriftet. Die zwei ähnlichen Strichfiguren sind mit Caitlin und Me!! beschriftet.",
     "Unter dem Skizzenbuch liegt ein platinener Ehering mit einer japanischen Gravur auf der Innenseite, die 永遠の愛 lautet. Sie bedeutet in etwa „endlose Liebe“, gefolgt vom Datum: 11.22.21. Er passt zu dem, den Justin trägt."
    ]}
   ]},
   {t:"Wohnzimmer", p:84, b:[
    "Staub schwebt durch den Raum, gefangen in Sonnenstrahlen. Gegenüber einem kleinen Fernseher steht ein altes Sofa, dazu verdorrte Pflanzen in unscheinbaren Töpfen. Der Fernseher flackert durch eine Reihe von Bildern, alle körnig und verzerrt. Auf dem Sofa liegt ein Laptop.",
    "Auf dem Couchtisch liegen ein paar Dinge verstreut. Darunter steht eine lila Handtasche. Obenauf liegt ein Exemplar von *The Other Me*, einem kürzlich beliebten Thriller über eine vermisste Schwester. Daneben steht eine bunte Tasse. Der Kaffee ist längst kalt und geronnen und riecht nach verdorbener Milch.",
    {t:"h", x:"Fumikos Schicksal"},
    "Sobald die Agenten sich einen Moment umgesehen haben, nähern sich leise Schritte den Flur entlang. Eine Gestalt mit kurzem Bob steht dort, halb verhüllt von der Dunkelheit des Flurs, abseits vom Fernseher. Die Frau fragt, wer sie seien und warum sie hier sind. Sie nennt 1063 Bower Street „das Haus unserer Eltern“. Ihre Stimme setzt bei diesen Worten merkwürdig aus und stottert wie ein abgenutztes VHS-Band. Das ist Fumiko Hamamoto, deren Erinnerungen so verändert wurden, dass sie glaubt, Evie Rowe zu sein.",
    "**Wenn sie fragen, wer sie ist,** erstarrt sie auf der Stelle, zuckt und flackert kaum merklich und verschwindet dann schnell den Flur hinab tiefer ins Haus.",
    "**Wenn Agenten ihr nachsetzen,** führt sie eine Spur aus zerrissenen und zerfetzten Bandstreifen, die sich durchs Haus schlängelt, zur Kellertür. Am unteren Ende der Tür liegen viele Bandstücke verheddert in einem Haufen und ziehen sich darunter hindurch; sie stinken nach Chlor.",
    {t:"h", x:"Auf den Laptop zugreifen"},
    "Auf dem Sofa liegt ein Laptop, mit einem Passwort gesperrt. Der Passwort-Hinweis lautet **„der Name deines ersten Haustiers“.** Das Passwort ist „Ollie“ und lässt sich in Caitlins Schlafzimmer finden oder aus dem Halsband in der Garage ableiten.",
    "**Wenn Agenten sich anmelden,** finden sie mehrere geöffnete Programme. Der Browser ist auf einer Nachrichtenseite geöffnet. Außerdem ist ein E-Mail-Programm offen, mit einer halb geschriebenen E-Mail an „Evelyn Wright“.",
    "Beim Navigieren durch den Laptop flackert der Bildschirm plötzlich ein paar Mal an und aus, ganz wie der Fernseher. Wenn er wieder angeht, hat der gesamte Bildschirm einen krankhaft blaugrünen Stich und spiegelt mehr, als ein leuchtender Bildschirm sollte. Die E-Mail erscheint immer wieder in der oberen rechten Ecke, die Maus wird zur Senden-Schaltfläche gezogen.",
    "**Wenn Agenten den Computer wieder ausschalten,** scheint die Spiegelung des Agenten, der ihn bedient hat, zu bleiben, wie in den Bildschirm eingebrannt.",
    {t:"handout", art:"brief", h:"[ENTWURF – NICHT GESENDET]", x:[
     "Hi, Evie. Ich weiß, dass wir seit allem mit Mom und Dad nicht viel geredet haben, aber ich wollte sehen, wie es dir geht. Glückwunsch zur neuen Veröffentlichung! Sieht cool aus, nicht dass ich viel davon verstehe, lol. Ich fahre immer noch das gleiche alte Auto.",
     "Es ist irgendwie komisch, allein wieder zu Hause zu sein. Einsam, vielleicht? Wenn du Lust hättest, mal herzukommen und zu Besuch zu sein, wäre das schön. Ich hatte vergessen, wie ruhig es hier ist. Ich bin durchs Haus gegangen, und es ist so viel von unserem alten Zeug da. Ich habe Ollies Halsband im Schuppen gefunden und weiß nicht, was ich damit tun soll. Vergraben, vielleicht? Und erinnerst du dich an die Stoffpuppe, die du als Kind hattest, die, die ich gruselig fand? Meistens habe ich viel Zeit damit verbracht, den Hinterhof rund um den alten Pool aufzuräumen. Ich dachte immer, er wäre tiefer, als er aussah, oder dass ich in den Abfluss gezogen würde. Ich glaube, deshalb bin ich in Panik geraten, als ich hineingefallen bin und du mich rausziehen musstest. Ich t"
    ]},
    {t:"h", x:"Fernsehen schauen"},
    "Der Fernseher ist nicht eingesteckt, läuft aber trotzdem. Wenn die Agenten versuchen, ihn auszuschalten, geht er wieder an.",
    "**Der Fernseher zeigt im Wechsel folgende Bilder, durchsetzt mit Rauschen:**",
    {t:"liste", x:[
     "Ein leerer, abgelassener Pool, der in der Sonne bleichweiß aussieht.",
     "Eine Klimaanlage an einem Fenster im Obergeschoss, die wütend rattert.",
     "Eine Treppe, die abwärts ins Dunkle führt. Einige Stufen sind zerbrochen.",
     "Ein alter kupferner Schlüssel auf weißem Hintergrund."
    ]}
   ]},
   {t:"Küche", p:86, b:[
    "Verblassendes Licht fällt durch die Jalousien und bildet Streifen auf Spüle und Arbeitsflächen. Unter einem Bein des kleinen Küchentischs steckt ein dünnes, vergilbtes Buch, um ihn zu stabilisieren; obenauf liegen ein Mobiltelefon und ein Stapel Rechnungen. Alles ist ordentlich an seinem Platz verstaut, keine Unordnung außer Staub. Eine Tür mit Fliegengitter führt hinaus in einen kargen Hinterhof mit Pool. Neben der Tür hängt ein hölzerner Schlüsselkasten, und eine verschlossene Tür führt hinab in den Keller.",
    {t:"hinweis", art:"gew", h:"Das erfahren Agenten, wenn sie die Küche und die Kellertür untersuchen:", x:[
     "Der Schlüsselkasten enthält Schlüssel zur Seitentür der Garage, zum Schuppen im Hinterhof und zum Auto in der Garage. Das Etikett am Schuppenschlüssel ist abgenutzt.",
     "Wenn jemand ein Ohr an die Tür drückt, sind gedämpfte Geräusche zu hören – lachende Kinder, eine tiefere Stimme, die ruft, Stöße von Rauschen.",
     "Das Schloss der Tür zum Keller ist alt und sieht zerbrechlich aus, lässt sich aber nicht mit gewöhnlichen Mitteln aufbrechen. Es wird von der Anomalie zugehalten und öffnet sich nur für den kupfernen Schlüssel aus dem Pool. In dem Moment, in dem er benutzt wird, schmilzt der Schlüssel zu Tropfen zähflüssiger Flüssigkeit wie der im Pool, im selben rötlichen Braun wie der Schlüssel selbst, und die Tür öffnet sich.",
     "Die Rechnungen sind nicht an Caitlin Rowe adressiert, sondern an einen Lewis Rowe. Die meisten sind überfällig und gemahnt. Zwischen den Rechnungen liegen einige Kopien von Lewis Rowes kürzlicher Sterbeurkunde, datiert vor fünf Monaten, und einige Kopien eines ordentlich getippten Briefes, der erklärt, dass Caitlin als Lewis' Tochter derzeit seine Finanzen aufarbeitet.",
     "Das Buch unter dem Tischbein ist ein Science-Fiction-Roman der alten Schule über künstliche Realität. Obwohl man ihm sein Alter ansieht, wirkt er nicht besonders viel gelesen. Der Buchrücken ist ungeknickt."
    ]},
    "Der Zugang zum Keller beginnt die Begegnung.",
    {t:"h", x:"Caitlins Telefon"},
    "Das Mobiltelefon auf dem Tisch ist leer.",
    "**Wenn die Agenten es aufladen und einschalten,** bleibt der Bildschirm einige Augenblicke auf dem Bild eines jungen Mädchens in einer geblümten Bluse mit langem braunem, zum Pferdeschwanz zurückgebundenem Haar stehen, das von der Kamera wegsieht. Es ist eine kleine Gestalt in der Ferne vor einem nicht zu verortenden, merkmallosen Hintergrund.",
    "Der Zugriff auf das Telefon erzürnt die Anomalie und veranlasst sie, im Wohnzimmer ein Paar jaulende Katzen (einsperrende Kleine Anomalien) zu manifestieren, um die Agenten wegzulocken und sie dazu zu verleiten, sie zu berühren.",
    {t:"hinweis", art:"anom", h:"Das sehen Agenten, wenn sie die Katzen anfassen und das Telefon durchsuchen:", x:[
     "Das Anfangsbild wurde in einem Fotoalbum namens Art Inspo gespeichert. Beim Durchblättern zeigt sich eine große Vielfalt an Bildern: Sehenswürdigkeiten der Gegend, ein paar Aufnahmen dieses Hauses, belebte Straßen in der Innenstadt von Ternion und der knochentrockene Pool im Hinterhof.",
     "Der Browser ist auf einer Pressemitteilung zur bevorstehenden Veröffentlichung von Evie Wrights Elektrofahrzeug geöffnet, datiert vor elf Tagen.",
     "Die letzte Nachricht an Evie ist neun Tage alt. Es ist eine leicht wackelige Handyaufnahme eines alten Fernsehbildschirms, die die jungen Zwillinge zeigt, wie sie darum wetteifern, wer schneller durch den Pool schwimmen kann. Die Person, die die Videokamera hält, lacht und feuert an, ein Klang, der durch die mehreren Medien, die er durchläuft, verzerrt ist. Der Text zum Video lautet: „Weißt du noch, als du noch gern schwimmen warst?? Gott, wir waren echt verdammt jung.“ Es gibt keine Antwort."
    ]},
    "Agenten können Evies Telefonnummer aus Caitlins Kontakten entnehmen."
   ]},
   {t:"Obergeschoss", p:87, b:[
    {t:"h", x:"Elternschlafzimmer"},
    "Unter der dicksten Staubschicht ist das Elternschlafzimmer karg und ordentlich. Der Lack am Türrahmen hat etwa sechzig Zentimeter über dem Boden Schrammen und Kratzer, wo ein Rollstuhl am Türrahmen angestoßen ist. Auf dem rechten Nachttisch liegt ein alter Ehering, ein schlichter Goldreif. Auf dem linken Nachttisch steht eine Vase mit Margeriten, die längst gestorben sind. Aus bestimmten Winkeln sehen sie lebendig aus, aber mit einem Blinzeln verwelken sie wieder.",
    "Ein Badezimmer grenzt an diesen Raum, mit staubigen Vorräten in einem Müllsack nahe der Tür – Herrenshampoo und Duschgel, ein alter Rasierer und eine halb leere Flasche Eau de Cologne, die nach Zitrus und Sandelholz riecht.",
    {t:"h", x:"Caitlins Schlafzimmer"},
    "Dieser Raum ist warm und behaglich, in satten Orangetönen und hellen Cremetönen. Das Schlafzimmer ist halb eingepackt oder vielleicht halb ausgepackt. Ein paar der Kartons wurden geöffnet und überhäufen den Nachttisch. Das Bett hat keine Laken, obenauf liegt eine kleine Decke.",
    {t:"hinweis", art:"gew", h:"Das erfahren Agenten, wenn sie das Schlafzimmer untersuchen:", x:[
     "Die kleine Decke, die vielleicht für ein Kleinkind oder ein kleines Kind gemacht wurde, ist an den Rändern ein wenig ausgefranst und offensichtlich heiß geliebt, kurz davor, unter dem Gewicht der Zeit zu zerfallen.",
     "Einer der herausgenommenen Gegenstände ist ein gerahmtes Foto eines lächelnden Jack Russell Terriers, den Schwanz mitten im Wedeln. Der Rahmen wurde mit Schaumstoffbuchstaben und -blumen verziert. ***Ollie!*** steht mit Marker rund um den Rahmen geschrieben, danach ein Herz."
    ]},
    {t:"h", x:"Evies Schlafzimmer"},
    "Dieses Schlafzimmer ist größtenteils eingepackt, Kartons säumen die Wände, und in der Mitte steht ein Bett. Die Vorhänge sind zugezogen. An den Wänden hängen noch zerrissene und eingerissene Poster einiger alter Gothic-Bands. Einige Kartons sind ausgepackt und durchwühlt. Es sind hauptsächlich altes Spielzeug, Krimskrams, Dinge von sentimentalem Wert.",
    "**Die Anomalie versucht, den Bereich zu Verderben, wenn Agenten ihn betreten.** Gegenstände sehen plötzlich neu statt alt aus, zerbröckeln aber, wenn etwas Lebendiges sie direkt berührt. Die Puppe kann in dieser Begegnung zerstört werden.",
    {t:"hinweis", art:"anom", h:"Das erfahren Agenten, während der Raum um sie herum zerbröckelt:", x:[
     "Beim Öffnen einiger weiterer Kartons kommen alte Bücher zum Vorschein – Fantasy und Science-Fiction, die zu anderen Welten entfliehen. Die abgegriffensten liegen in einem bestimmten Karton, eine Reihe über Weltraumforschung in ferner Zukunft. Eine Notiz im Einband des ersten Bandes lautet: ***„Für Evie – Das war meine Lieblingsreihe als Kind, und ich hoffe, sie zeigt dir, wie man eine bessere Welt macht. In Liebe, Dad.“***",
     "In der Nachttischschublade liegen ein paar alte, ein wenig vom Alter vergilbte Fotos. Einige zeigen eine junge Evie, identisch mit Caitlin, mit ein paar Freunden vor einem Freizeitpark. Eines zeigt Evie und Caitlin zusammen neben der Palme.",
     "Auf dem Bett liegt eine Puppe – zerlumpt, mit teils fehlendem Haar und einem fehlenden Knopfauge. Sie wurde offensichtlich von Hand gemacht, und jemand hat sich die Mühe gemacht, sie ordentlich anzuziehen."
    ]}
   ]},
   {t:"Büro", p:88, b:[
    "Das Büro ist zwischen zwei Leben aufgeteilt. Das eine ist von Staub bedeckt – Aktenschränke, ein Eckschreibtisch, der sich teilweise um den Raum erstreckt, mit einem toten Desktop-Computer darauf. Die andere Hälfte ist neu – ein kleiner, beiseitegestellter Schreibtisch, bedeckt mit Farben, einem alten Skizzenbuch, Bleistiften, Pinseln. Mehrere schwarze Müllsäcke stehen neben einem offenen Aktenschrank, halb gefüllt mit Papierkram. Einer ist auf die Seite gekippt, Abfall quillt heraus. Ein relativ neues Laptop-Modell liegt geschlossen auf dem Schreibtisch.",
    {t:"hinweis", art:"gew", h:"Das erfahren Agenten, wenn sie das Büro untersuchen:", x:[
     "Der gesamte Papierkram im Müll stammt frühestens von vor einigen Jahren – alte Steuerformulare, alte Rechnungen und anderer Papierkram und Abfall. Obenauf liegen, als überlege noch jemand, ob sie überhaupt in den Sack gehören, ein paar Kopien einer älteren Sterbeurkunde für eine Irene Rowe, datiert vor sechs Monaten.",
     "Ein Bilderrahmen liegt mit dem Bild nach unten. Aufgerichtet zeigt er ein altes Foto von zwei Erwachsenen und zwei Kindern, die Mädchen gleich groß und nahezu identisch. Die Gesichter der Mädchen sind von der Zeit abgetragen, die der Erwachsenen bleiben vollkommen klar. Hinter ihnen ist die Form von 1063 Bower Street merkwürdig gedehnt, als hätte etwas ihr Bild wie Karamell breiter gezogen. Je länger es aufrecht steht, desto gedehnter wirkt das Haus.",
     "Ein paar eselsohrige Science-Fiction-Bücher aus den Achtzigern liegen noch auf dem Schreibtisch mit dem Desktop-Computer. Zwei sind umgefallen.",
     "Auf dem kleinen provisorischen Schreibtisch liegen verschiedene grobe Bleistiftskizzen. Sie umreißen zwei identische Mädchen, die einander anstarren, mit einer Art flacher Fläche dazwischen – entweder ein Spiegel oder ein Fenster. Nicht alle Entwürfe sind genau gleich. Einige zeigen ein Mädchen, das die flache Fläche berühren will, während das andere sich von ihr abwendet, ihr Gesicht ein Wirbel aus verflüssigter Textur. Auf diesen Bildern fühlt sich das verzerrte Gesicht nass an, klebt aber nicht und hinterlässt keinen Fleck. Einige der Entwürfe sind gewaltsam durchgestrichen."
    ]}
   ]}
  ],
  beg: [
   {t:"Abstieg", p:88, b:[
    "Das Öffnen der Kellertür offenbart eine Treppe aus knarrenden Holzstufen. Einige der Stufen wirken lose. Die Bretter sind über Jahre der Benutzung abgeschabt und abgetreten. Sie führen abwärts und biegen dann nach rechts zu einer zweiten Treppe ab. Die Treppe endet dort, wo der Boden des Kellers sein sollte. Stattdessen aber hält der Abstieg auf einem kurzen Absatz inne und wiederholt dann dieselben Stufen abwärts und dann nach rechts.",
    "Am Ende jeder Treppe steht ein Fernseher, der durch eine Reihe von Bildern flackert. Die Treppe führt weit hinab ins Dunkel. Die Luft wird beim Abstieg schwerer und feuchter. Gelegentlich verschwindet etwas von der Größe eines großen Hundes um die Ecke nach rechts.",
    "**Wenn Agenten versuchen, die Treppe wieder hinaufzusteigen, um zu gehen,** hält die Anomalie sie nicht auf. Sie will in Ruhe gelassen werden, und wenn sie nichts im Keller behelligen, lässt sie sie nach oben zurückkehren, um das Haus zu erkunden.",
    "**Wenn die Agenten den Fernseher zerstören,** strömt Wasser aus dem Bildschirm und dem VHS-Schlitz, mit so hohem Druck, dass der Fernseher die Treppe hinabstürzt. Er landet am Ende der nächsten Treppe, schließlich dem Ende: dem eigentlichen Keller.",
    {t:"hinweis", art:"gew", h:"Diese Szenen flackern über die Treppenhaus-Fernseher:", x:[
     "Ein leerer, abgelassener Pool, bleichweiß.",
     "Ein Jack Russell Terrier mit blauem Halsband, der in aufgeregten Kreisen rennt, den Schwanz wedelnd.",
     "Eine Tür mit abgeschabter und abgeplatzter weißer Farbe, angelehnt.",
     "Eine Klimaanlage an einem Fenster im Obergeschoss, die wütend rattert.",
     "Eine Treppe, die abwärts ins Dunkle führt. Einige Stufen sind zerbrochen.",
     "Ein alter kupferner Schlüssel auf weißem Hintergrund.",
     "Ein junges Mädchen in einer Bluse mit Blumenmuster und langem braunem, zum Pferdeschwanz zurückgebundenem Haar, das von der Kamera wegsieht.",
     "Ein junges Mädchen in einer weißen Bluse und langem braunem, offenem Haar, das in den Pool klettert – manchmal voll, manchmal leer."
    ]}
   ]},
   {t:"Keller", p:89, b:[
    "Die Kellerdecke von 1063 Bower Street hängt tief, aufgedunsen von Feuchtigkeit. Der Raum wirkt zu klein für das, was er enthält. An der der Treppe gegenüberliegenden Wand steht ein weiterer Fernseher mit einem Videorekorder darunter, auf dem Bildschirm Bild um Bild, weniger verschwommen als auf den Geräten oben. Hier schleichen sich auch andere Bilder ein: ein Paar Hände, die zwischen Kabel greifen, Stricknadeln, die einen dunkelblauen Pullover stricken, und jemand, der die Leine am Halsband eines zappeligen Labradors befestigt. Eine VHS-Kassette steckt halb im Player, und aus ihr quillt ein verhedderter Ozean aus schwarzem Band. Unter der einzelnen flackernden Glühbirne, die von oben hängt, sieht das Band glitschig und nass aus.",
    "Eine Gestalt sitzt im Schneidersitz auf dem Boden vor dem Fernseher, in Schichten über Schichten von schwarzem Band gewickelt: Caitlin Rowe.",
    {t:"h", x:"Die Anomalie"},
    "Caitlin ist in Spulen abgewickelten VHS-Bandes gehüllt, regungslos und still. Jeder Versuch, mit der Gestalt zu kommunizieren, bleibt ohne Antwort. Ihre Augen sind kaum durch die Schichten schwarzen Bandes zu erkennen. Hin und wieder steigen Tränen auf und fallen, gleiten über und unter Schichten von schwarzem Band. Sie wird von der Anomalie verzehrt, die sich von ihrer Nostalgie nährt. Vier Katzen und drei Hunde haben sich auf der anderen Seite des Raumes versammelt und eingerollt, liegen auf der Seite, die Augen glasig, aber atmend. Eine schwarze Katze mit einem weißen Fleck über dem linken Auge ist unter ihnen.",
    "Am Rand des Raumes sitzen sieben menschliche Gestalten, ebenso in Band gehüllt, auf der Seite oder auf dem Rücken liegend.",
    "Über die Seite des Fernsehers gesackt, praktisch darum gewickelt, liegt eine Frau mit kurzem Bob. Ihre Gesichtszüge flackern merkwürdig, manchmal eine Japanerin Mitte bis Ende dreißig – die vermisste Fumiko Hamamoto – und manchmal eher wie die Bilder von Evie Wright, die die Agenten im Haus gesehen haben, ob gegenwärtig oder vergangen. Ihre Augen wandern in dem Moment von Caitlin zu den Agenten, in dem sie eintreffen.",
    {t:"h", x:"Kommunikation"},
    "Die Anomalie kommuniziert über den Fernseher mit einer Mischung aus Text auf dem Bildschirm, verzerrten Aufnahmen einer Frauenstimme und Fumiko, die direkt spricht.",
    "**Wenn sie nach einem Namen gefragt wird,** nennt sie sich Evie.",
    "Sie spricht bis zu zwei der Agenten als Caitlins Eltern Irene und Lewis an, unabhängig vom Aussehen, und versucht, sie dazu zu bringen, bei einer Fantasie von Caitlins altem Leben mitzuspielen. Alle anderen Agenten bezeichnet sie als Nachbarn aus nahe gelegenen Häusern.",
    "Die Anomalie schlägt aggressiv um, wenn jemand versucht, die VHS-Kassette zu entfernen, Fumiko zu sagen, wer sie wirklich ist, oder die in Band gewickelten Gestalten abzuwickeln.",
    {t:"h", x:"Die Falle schnappt zu"},
    "Der erste Schachzug der Anomalie ist der Versuch, die Agenten in ihre konstruierte Version der Vergangenheit zu ziehen. Die Szene flackert und wechselt zwischen der bandbedeckten Gegenwart und einer idyllischen Vergangenheit, wobei die kindlichen Gestalten von Caitlin und Evie die heutigen Caitlin und Fumiko ersetzen. Das Licht ist weich und gelb. Ein Gefühl von Geborgenheit erfüllt die Luft. Es riecht nicht mehr nach Nässe und Fäulnis, sondern nach der angenehmen Muffigkeit eines sauberen Kellers. Caitlin spricht hier, lacht ein Kinderlachen und lädt die Agenten ein, sich zu ihnen zu setzen und fernzusehen. Ihre Hand fühlt sich kalt und glitschig an.",
    "Das Bild ist unvollkommen und flackert zwischen idyllischer Vergangenheit und schrecklicher Gegenwart, wenn Agenten irgendetwas aus der Gegenwart ansprechen.",
    {t:"h", x:"Kämpfen"},
    "**Wenn das Band, das irgendein Opfer festhält, entfernt, durchtrennt oder anderweitig zerstört wird,** schlägt die Anomalie aggressiv um. Das Band windet und peitscht sich, schlägt wild um sich. Der Fernseher speit eine Welle Rauschen aus. Das Band beginnt, den Raum zu verschlingen, verschmilzt zu einer schweren, klebrigen Masse. Die VHS-Kassette wird schnell unerreichbar und kann nicht mehr anvisiert werden. Agenten müssen anomale Fähigkeiten einsetzen oder mit dem Opfer fliehen, das sie zuerst gerettet haben. (Siehe Aus dem Haus entkommen.)",
    {t:"h", x:"Caitlin und Fumiko retten"},
    "Der einzige Weg, die Gefangenen sicher zu retten, besteht darin, der Anomalie zu zeigen, dass manche Teile der Vergangenheit nicht zurückgewonnen werden können. Wenn die Agenten **Caitlin und Fumiko der Gegenwart näherbringen** können – insbesondere in Bezug darauf, dass Evie Wright ein völlig anderes Leben führt, weit entfernt von diesem –, dann verliert die Anomalie womöglich ihren Griff auf die im Keller Gefangenen.",
    "**Für Caitlin gehören dazu:**",
    {t:"liste", x:[
     "Aktuelle Neuigkeiten über Evie",
     "Die in Evies Zimmer zurückgelassene Puppe",
     "Die ungesendete E-Mail, die Caitlin auf ihrem Laptop geschrieben hat",
     "Caitlins Kinderdecke, jetzt alt und abgewetzt",
     "Evie anzurufen mit der Nummer aus Caitlins Telefon"
    ]},
    "**Für Fumiko gehören dazu:**",
    {t:"liste", x:[
     "Der in der Garage gefundene Ring",
     "Den Pullover zu beschreiben, den sie für Justin gestrickt hat",
     "Erinnerungen an die jüngsten Streitereien mit Justin",
     "Sie zu Einzelheiten über Evie zu drängen, schneller als die Anomalie sie ihr einflößen kann"
    ]},
    "**Wenn Caitlin und Fumiko aus ihren Erinnerungen geholt werden,** reagiert die Anomalie nicht sofort aggressiv, weil sie sie behaglich halten will. Die Szenen im Fernseher werden gestört und verzerrt, von anderen Erinnerungen durchbrochen, während die Anomalie die Kontrolle verliert. Die Anomalie ist noch nicht fangbar. Der Versuch, sie zu fangen oder Caitlin und Fumiko aus dem Keller zu führen, steigert ihre Wut.",
    "Eine schattenhafte, rauschende Kopie der jungen Evie Wright kriecht aus dem Fernseher. Das Bild von Evie flackert schnell zwischen heute und jung, ihr Kopf nach rechts geneigt. Die VHS-Kassette ragt aus einem blutleeren Loch an der Seite ihres Halses. Caitlin sieht darin ihre Schwester und kämpft weiterhin damit zu verstehen, was real ist. Diese Erscheinung beginnt, die Agenten durchs Haus zu verfolgen, und schwingt einen endlosen Strom schwarzen Bandes als Waffe.",
    "Die Ripple Gun kann diese Version der Anomalie zerstören, indem man auf das VHS-Band schießt, aber der Normale Aktenkoffer funktioniert erst, wenn die Anomalie erschöpft ist. Wenn Fumiko wieder zu sich gekommen ist, schlägt sie vor, Caitlin hinaus in die Sonne zu bringen, wo sie die echte Welt sehen kann."
   ]},
   {t:"Aus dem Haus entkommen", p:91, b:[
    "Die Agenten müssen sich durch eine sich verziehende Version des Hauses bewegen, während die Anomalie versucht, sie zu verfolgen. Türen nach draußen fehlen oder öffnen sich in Flure. Räume gehen ineinander über. Jeder Flur ist eine Sackgasse. Fenster öffnen sich auf Trockenbauwände.",
    "Das Haus durchläuft immer die folgenden Räume in dieser Reihenfolge, wobei jede ursprüngliche Logik des Hauses von der Anomalie über Bord geworfen wurde. Das ganze Haus gewährt der Anomalie jetzt Domänenvorteile. Agenten entkommen, indem sie durch jeden Raum gehen oder anomale Methoden einsetzen.",
    {t:"h3", x:"1 Wohnzimmer"},
    "Der Boden des Wohnzimmers ist angeschwollen, bis er sich rundet wie eine Blase kurz vor dem Platzen. Er wankt und schaukelt, Gegenstände rutschen über den Boden. Beim Rutschen scheinen sich manche zu verziehen und zu dehnen, knarrend, bis sie in Stücke zerbrechen. Hundert Exemplare von *The Other Me* sind an einer Wand gestapelt.",
    {t:"h3", x:"2 Evies Schlafzimmer"},
    "In dem, was Evies Schlafzimmer sein sollte, sitzen viele Versionen ihrer Kinderpuppe. Keine gleicht der anderen. Manche haben ein fehlendes Auge, wie die echte. Andere haben das gegenüberliegende Auge fehlend, gar keine Augen oder Augen, die ans Kleid oder seitlich an den Kopf genäht sind. Poster lösen sich von den Wänden und enthüllen darunter glänzende schwarze Bahnen von Band.",
    {t:"h3", x:"3 Büro"},
    "Das Innere des Büros zieht sich auf ein winziges Loch in der Mitte zusammen. Das einzige Objekt, das unversehrt bleibt, flattert neben dem Loch. Es ist einer der Entwürfe der Zeichnung, der die zwei Mädchen zeigt, die in entgegengesetzte Richtungen schauen, beide zur flachen Fläche in der Mitte gezogen und von ihr verzerrt.",
    {t:"h3", x:"4 Küche"},
    "Was die Küche war, ist nun voller streunender Tiere, die in weit aufgerissener Panik durch den Raum jagen. Mitten darin sitzt ein Jack Russell Terrier mit warmen braunen Augen und einem blauen Halsband. Caitlin nennt den Hund Ollie und versucht, ihn zu begrüßen. Ist Caitlin stabil genug, um zu wissen, dass es nicht wirklich Ollie ist, führt der Hund sie aus der Küche hinaus und dann zurück in eine andere Version davon, mit einer Tür, die in den Hinterhof führt. Andernfalls schwärmen die Tiere um sie herum und versuchen, sie von den Agenten wegzuziehen.",
    {t:"h3", x:"5 Zurück in den Keller"},
    "Nach allen anderen Räumen finden sie sich wieder im Keller. Wo der Fernseher stand, ist jetzt die Tür zum Hinterhof, flach auf dem Boden. Die Schwerkraft ruckt und ändert sich, wenn die Agenten in den echten Hinterhof treten.",
    {t:"h3", x:"6 Hinterhof"},
    "Das Entkommen aus dem Haus führt direkt zum Pool, voll von zähflüssiger grüner Flüssigkeit, selbst wenn die Agenten ihn vorher gemieden haben. Die falsche Evie jagt ihnen hinaus in die offene Sonne nach und verliert dabei ihre Domänenvorteile.",
    {t:"h", x:"Die Anomalie erschöpfen"},
    "**Wenn Agenten sie in den Pool locken,** haftet die seltsame grüne Flüssigkeit an dieser falschen Evie und ihrem schwarzen Band, beschwert sie und entzieht ihr Energie. Sie erschöpft sich beim Versuch zu entkommen und ist dadurch anfällig für den Aktenkoffer.",
    "**Wenn Caitlin mit einem Telefon ihre Schwester Evie anruft** oder in genau diesem Moment eine andere Verbindung zu ihrer echten Schwester herstellt, beginnt das Band der Anomalie an den Enden zu brennen und verbrennt schließlich diese falsche Evie, sodass nur eine einzelne alte VHS-Kassette zurückbleibt, die gefangen werden kann.",
    "**Wenn Agenten mit irgendwelchen Opfern fliehen, um sie zu retten, und später zurückkehren,** entkommt die Anomalie, während sie fort sind."
   ]}
  ],
  nach: [
   {t:"Ausgänge", p:92, b:[
    "1063 Bower Street wird nicht mehr dasselbe sein. Das Haus sieht größtenteils gleich aus, aber das Innere ist durchtränkt von abgestandenem Wasser, die Luft riecht schwach nach Poolchemikalien. Tiere stürmen aus dem Haus und entkommen endlich den Klauen der Anomalie. Andere Bewohner der Straße schauen wegen des Lärms und der Verwirrung aus ihren Häusern, einige werden möglicherweise zu Losen Enden.",
    "**Wenn die Anomalie entkommen ist,** wird sie wahrscheinlich als Nächstes Evie verfolgen, in Anbetracht dessen, wie verbunden sie mit ihrer Zwillingsschwester ist. Sie wird sich eher von anderen in Evies Umfeld nähren als von ihr selbst. Evie Wright ist kein besonders nostalgischer Mensch.",
    "**Wer von der Anomalie gestohlen wurde und überlebt hat,** leidet unter anhaltender Verwirrung und Gedächtnisproblemen. Menschen und Orte aus ihrer Vergangenheit zu sehen, kann verstörend sein, bis ihr Geist diesen Konflikt aufgelöst hat. Irgendwann fühlt sich das, was in diesem Keller geschah, wie ein schlechter Traum an, aber es ist kein Ort, an den einer von ihnen zurückkehren möchte.",
    "**Wer von der Anomalie betroffen, aber nicht gefangen war,** erlebt eine schockierende Rückkehr in die Realität. Manche, wie Justin und Rebecca, haben mit einem „Nostalgie-Kater“ zu kämpfen, der ihre Erinnerungen jetzt überrannt und schwer fassbar wirken lässt.",
    {t:"h", x:"Lose Enden"},
    "**Rebeccas Katze „Felix“ verschwindet.** Rebecca ist am Boden zerstört, schluchzt auf der Vortreppe, während Jodie sie grimmig tröstet. Wurde Cooper gerettet und ihnen zurückgebracht, tun sie den ganzen Vorfall wahrscheinlich als Reihe stressbedingter Halluzinationen ab.",
    "**Fumiko beharrt darauf, nicht nach Hause zu wollen.** Obwohl ihre Erinnerungen verschwommen sind, noch halb mit der Persona von Evie vermischt, erfüllt sie der Gedanke daran mit Grauen. Sie lässt sich überreden, mit Justin zu sprechen, aber sich selbst überlassen, bittet sie darum, das Telefon eines Agenten zu leihen, um ihren Bruder anzurufen, der auf der anderen Seite der Stadt lebt. Die Erfahrung hat sie aus der Straße entwurzelt.",
    "**Justin erinnert sich plötzlich an seine bevorstehende Scheidung von Fumiko.** Er weiß, dass etwas Seltsames mit ihm geschah, schämt sich aber, so lange in Verleugnung gewesen zu sein. Bekommt er einen kurzen Abschluss mit Fumiko und die Bestätigung, dass sie in Sicherheit ist, will er nie wieder über diese Erfahrung sprechen.",
    "**Wenn irgendeine Beziehung von der Anomalie betroffen war,** etwa durch die Rückkehr eines Haustiers, kehrt die Realität für sie sofort und plötzlich zurück. Sie versuchen möglicherweise, den Agenten zu kontaktieren.",
    "**Caitlin braucht wahrscheinlich ärztliche Hilfe.** Ihre Verwirrung ist tief verwurzelt. Sie wird Fumiko versehentlich Evie nennen und bezeichnet die Agenten womöglich sogar mit den Rollen, die sie im Keller gespielt haben – ihre Eltern, ihre Nachbarn und so weiter. Sie bittet die Agenten, ihr zu helfen, ihre Schwester um Hilfe zu kontaktieren. Sie ist verängstigt von der modernen Straße, wird aber mit Hilfe der echten Evie schnell wieder in der Realität ankommen. Der Gedanke, überhaupt in das Haus zurückzukehren, stößt sie ab, und sie hält es in der Einfahrt kaum aus.",
    "**Wenn Caitlin Evie erzählt, was geschehen ist,** wird Evie sich darauf konzentrieren, Anomalien zu verstehen. Sie hat genug Einfluss, Geld und Willenskraft, um der Agency zum Dorn im Auge zu werden. Wenn die Agenten nicht aufpassen, könnte sie zum künftigen Ziel einer Market Disruption werden."
   ]},
   {t:"Vault-Anforderung", p:93, b:[
    {t:"anforderung", h:"Fotografisches-Gedächtnis-Daumenkino", en:"Photographic Memory Flipbook", preis:23, b:[
     "Nenne eine für immer verlorene Information (das Passwort eines verstorbenen Verwandten, den Inhalt eines vergriffenen Buches, ein Programm auf einer beschädigten Festplatte) und gib eine Qualitätssicherung aus einer beliebigen Qualität aus, um die Seiten dieses streichholzschachtelgroßen Büchleins durchzublättern. Auf diese Weise aktiviert, zeigt das Daumenkino die erfragte Information – immer direkt, aber auf eine Weise, die zu künstlerischer Interpretation einladen kann."
    ]}
   ]},
   {t:"Anomalie-Fähigkeit", p:93, b:[
    {t:"faehig", h:"Gedächtnislücke", en:"Memory Lapse", x:"Sie wollten ohnehin das Thema wechseln. Wenn ein Ziel spricht, unterbrich es mit einer Anschlussfrage („Wer hat das gesagt?“, „Wann war das noch mal?“, „Und wo warst du zu dem Zeitpunkt?“) und würfle auf Doppelzüngigkeit.", erg:[
      ["ok","**Bei Erfolg** verliert das Ziel den Faden und erinnert sich an nichts von dem, worüber es gerade gesprochen hat – selbst wenn es darauf angesprochen wird, ihm Beweise vorgelegt werden oder es seine Schritte zurückverfolgt."],
      ["plus","**Bei jeder dritten {3}** wähle eine:\n– Dieser Effekt hält für immer an.\n– Das Ziel vergisst eine weitere Sache, die du mündlich erwähnst.\n– Das Ziel vergisst auch diese gegenwärtige Interaktion, sobald sie vorbei ist."],
      ["nein","**Bei Fehlschlag** vergisst das Ziel alles. Es gibt nichts, woran es sich erinnert. Du erhältst sein gesamtes Leben als Erinnerungen in deinem Kopf, alles auf einmal, kannst sie ihm aber mit keinem Mittel zurückgeben."]
     ], b:[]}
   ]}
  ]
 }
};
/* GESTALTUNG: Seitenzahlen = Dateinummern (S0NN), wie im Inhaltsverzeichnis (Bower Street ab S. 76); die im Buch aufgedruckte Fußzeile steht jeweils eins höher.
 S. 76: Eröffnungsseite = Abschrift des 911-Anrufs (Zeilennummern 1–41 am Rand, Filmstreifen über der unteren Hälfte, Titelschriftzug BOWER STREET, „BY: KAY W.“); Name „Justin“ nur als J.H., Telefonnummer geschwärzt.
 S. 78: Optionale Ziele im Buch als Kasten; Vermisstenplakat (Katze) nur im Text beschrieben, Platzhalter als Schild-Handout.
 S. 79: Chaos-Effekte ohne ▲; Manifestieren mit zwei Unterabsätzen (Gestalt/Vision), im Feld x durch Leerzeile getrennt.
 S. 80–81: Hinweislisten als „?“-Symbol (gew) bzw. Anomalie-Symbol (anom); Abschnitte 1059/1058 Bower St. als h im Abschnitt Sycamore Heights.
 S. 84: E-Mail-Entwurf „[DRAFT - UNSENT]“ als Kasten mit Senden-Symbol, endet mitten im Wort („Ich t“) – bewusst so übersetzt. Fernseher-Bilder (S. 84) als einfache Liste, Treppen-Fernseher (S. 88) als Hinweisliste.
 S. 90: Entkommen aus dem Haus: sechs nummerierte Räume (handschriftliche Ziffern 1–6, Spaltenfolge 1-2-3 links, 4-5-6 rechts) als h3 „1 Wohnzimmer“ usw.
 S. 91: Ausgänge als Fließtext mit h „Lose Enden“ (keine Zwei-Spalten-Ausgangsbox).
 S. 92: Vault-Anforderung Preis 23; Anomalie-Fähigkeit mit Erfolg/jede dritte 3/Fehlschlag.
 Kein Sonderkasten neben den Chaos-Effekten, keine Karten/Werte. Content Warnings aus dem Inhaltsverzeichnis (Autorin Kay W.). */
